<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hasil Ujian — FRExam</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{font-family:Inter,sans-serif;color:#1f2937}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:linear-gradient(135deg,#f5f7fa,#e8eef7)}.card{position:relative;max-width:780px;width:100%;padding:36px;text-align:center;background:#fffd;border:1px solid #fff;border-radius:25px;box-shadow:0 22px 45px #23395d18;overflow:hidden}.card:after{content:"✦";position:absolute;right:-38px;top:-67px;color:#a0b4d138;font-size:175px}.mark{position:relative;z-index:1;display:grid;place-items:center;width:58px;height:58px;margin:auto;border-radius:18px;background:#e8eef7;font-size:29px}.eyebrow{color:#365d92;font-size:12px;font-weight:800;letter-spacing:1px;margin:17px 0 7px}.card h1{margin:0;font-size:25px}.muted{color:#64748b;margin:0}.result-row{display:grid;grid-template-columns:145px 1fr;gap:18px;align-items:center;text-align:left;margin:24px 0 10px}.score-area{text-align:center}.score-ring{width:142px;height:142px;border-radius:50%;display:grid;place-items:center;margin:auto;background:conic-gradient(#23395d calc({{ $attempt->score }} * 1%),#e8eef7 0);position:relative}.score-ring:before{content:"";width:116px;height:116px;border-radius:50%;background:#fff;position:absolute}.score{position:relative;font-size:44px;font-weight:800;color:#23395d}.score small{font-size:15px}.motivation{padding:20px;border-radius:16px}.motivation i{display:inline-grid;place-items:center;width:44px;height:44px;border-radius:13px;background:#fff9;font-style:normal;font-size:24px}.motivation h2{margin:11px 0 6px;font-size:18px}.motivation p{margin:0;line-height:1.6;font-weight:600}.orange{background:#fff1df;color:#9a4b10}.blue{background:#e8f2ff;color:#24558e}.green{background:#e2f7e8;color:#187342}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:27px}.item{padding:15px 8px;background:#f5f7fa;border:1px solid #eef2f7;border-radius:13px}.item strong{display:block;font-size:22px;color:#23395d;margin-bottom:5px}.item span{font-size:11px;color:#64748b}.button{display:inline-block;margin-top:27px;border-radius:11px;background:#23395d;color:#fff;padding:13px 19px;font:800 14px Inter;text-decoration:none}@media(max-width:600px){.card{padding:28px 20px}.result-row{grid-template-columns:1fr;text-align:center}.motivation{text-align:left}.grid{grid-template-columns:1fr}}</style></head><body><main class="card">@php($score=(int)$attempt->score) @if($score<=50) @php($theme='orange') @php($icon='🌱') @php($message='Terus semangat yaa, terus mencoba, kamu pasti bisa!') @elseif($score<=75) @php($theme='blue') @php($icon='⭐') @php($message='Bagus! Jadikan motivasi untuk menggapai nilai yang lebih tinggi!') @else @php($theme='green') @php($icon='🏆') @php($message='Hebat sekali! Pertahankan keberhasilanmu!') @endif<i class="mark">🏆</i><p class="eyebrow">UJIAN SELESAI</p><h1>{{ $exam->title }}</h1><p class="muted">Kerja bagus, hasil Anda sudah tersimpan.</p><section class="result-row"><div class="score-area"><div class="score-ring"><p class="score">{{ $attempt->score }}<small>/100</small></p></div><p class="muted" style="margin-top:9px">Nilai akhir</p></div><article class="motivation {{ $theme }}"><i>{{ $icon }}</i><h2>Pesan untukmu</h2><p>{{ $message }}</p></article></section><section class="grid"><article class="item"><strong>{{ $attempt->correct_count }}</strong><span>Jawaban benar</span></article><article class="item"><strong>{{ $attempt->wrong_count }}</strong><span>Jawaban salah</span></article><article class="item"><strong>{{ floor($attempt->time_used_seconds / 60) }}m</strong><span>Waktu digunakan</span></article></section><a class="button" href="{{ route('dashboard') }}">← Kembali ke Dashboard Siswa</a></main></body></html>
